    "answerKo": "러셀 1:18.518, 안토넬리 1:18.811의 실제 랩입니다. 거리별 속도를 겹쳐 감속·가속 구간을 비교합니다. 공개 FastF1 기반 데이터이며 차량의 전체 원시 센서 데이터는 아닙니다.",
    "answerEn": "These are Russell's 1:18.518 and Antonelli's 1:18.811 laps. The speed traces show braking and acceleration along the lap, using public FastF1-derived telemetry rather than full raw car sensor data.",
